 if(scene%5==2){var policy=TechniqueTerrain.policy(fruits.get(i),id);int changed=TechniqueTerrain.brokenTotal(TechniqueTerrain.fruitKey(fruits.get(i))+"/"+id)-terrainBefore;boolean ice=world.getBlockState(new BlockPos(680,99,81)).is(Blocks.PACKED_ICE)||world.getBlockState(new BlockPos(680,99,80)).is(Blocks.PACKED_ICE);check(key+"/terrain",policy!=null&&(policy.mode()==TechniqueTerrain.Mode.DESTRUCTIVE?changed>0&&changed<=policy.blocks():policy.mode()==TechniqueTerrain.Mode.TRANSFORM?ice:changed==0),"changed="+changed+" ice="+ice+" policy="+policy);return;}
 if(id.equals("hyogaheki")){check(key+"/peaceful",normal.getHealth()==500&&IceDefense.isActive(caster),"finite defense no direct damage");}else{double expected=m.damage()+(id.equals("brachiolauncher")?13.5:0);check(key+"/damage",Math.abs(500-normal.getHealth()-expected)<.02,"actual loss="+(500-normal.getHealth())+" expected="+expected);check(key+"/attribution",attributed,"native accepted damage owner");}
 if(Set.of("headbutt","ulzugan","brachiobober","attackjump","ulmeteor").contains(id)){double d=caster.position().distanceTo(start);check(key+"/movement",d>(id.equals("ulzugan")?11:id.equals("ulmeteor")?11:5)&&d<(id.equals("ulzugan")?13:id.equals("ulmeteor")?13:8),"actual complete charge/landing travel="+d);}
